 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(cell for row in grid for cell in row)
    bg = counts.most_common(1)[0][0]
    marker = max((color for color in counts if color != bg), key=lambda color: counts[color])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    r0, r1 = min(r for r, c in points), max(r for r, c in points)
    c0, c1 = min(c for r, c in points), max(c for r, c in points)
    out = [row[:] for row in grid]

    # Complete the perimeter of the marker bounding box.
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            if (r in (r0, r1) or c in (c0, c1)) and grid[r][c] == bg:
                out[r][c] = 2

    # Complete gaps along unusually well-populated marker lines. Sparse
    # two- and three-marker alignments are left alone.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == marker]
        if len(cols) >= 4:
            for a, b in zip(cols, cols[1:]):
                for c in range(a + 1, b):
                    if grid[r][c] == bg:
                        out[r][c] = 2
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == marker]
        if len(rows) >= 4:
            for a, b in zip(rows, rows[1:]):
                for r in range(a + 1, b):
                    if grid[r][c] == bg:
                        out[r][c] = 2
    return out


